LINES = [{'id': 'rule', 'text': 'In this town, if you laugh at someone, you fall asleep for one hour. Right where you stand.'}, {'id': 'bo', 'text': "My friend Bo laughed at the mailman's split pants. Bo will be napping on this sidewalk until four."}, {'id': 'cake', 'text': 'On Monday, Gus the baker dropped a cake on his own head. Forty-one customers laughed. Forty-one naps.'}, {'id': 'pillows', 'text': 'Now Gus sells pillows next to the cupcakes. Pillows cost five dollars. They sell out every day.'}, {'id': 'dad', 'text': 'My dad tells the worst jokes in town. Nobody laughs, so he laughs at himself. He never even yawns.'}, {'id': 'gramps', 'text': "Grandpa hasn't laughed since 1975. He only says one thing about it. Laugh with people, Mia. Never at them."}, {'id': 'rich', 'text': "Then there's Mr. Rich. He hasn't laughed in fifty years either. He says laughing is for poor people."}, {'id': 'bank', 'text': 'On Friday, Mr. Rich did a chicken dance in the bank. Two guards laughed, fell asleep, and he took every gold bar.'}, {'id': 'street', 'text': 'Then he danced down Main Street. The police laughed. The bus driver laughed. Everybody hit the ground.'}, {'id': 'noon', 'text': 'By noon, three thousand people were snoring. Only two of us were awake. Me, pinching my arm, and Grandpa.'}, {'id': 'seen', 'text': "Grandpa didn't even smile at the dance. He looked so sad. He whispered, I've seen that dance before."}, {'id': 'fair', 'text': 'In 1975, a lonely boy named Richie did that same dance at the school fair, to make friends.'}, {'id': 'slip', 'text': 'He slipped and fell into the fountain. Grandpa laughed first. Then everyone did. Fifty kids, fifty naps.'}, {'id': 'alone', 'text': 'Richie sat in that cold water alone for a whole hour. Nobody helped him. Richie grew up to be Mr. Rich.'}, {'id': 'wobble', 'text': 'Now Mr. Rich turned and did the chicken dance right at me. My lips wobbled. I almost laughed.'}, {'id': 'brave', 'text': 'So I did the bravest thing I know. I did the chicken dance too, badly, and laughed at myself first.'}, {'id': 'gramps2', 'text': 'Grandpa flapped his elbows next to me, and laughed for the first time in fifty years. He stayed awake.'}, {'id': 'with', 'text': "Then Mr. Rich laughed too. Not at us. With us. Nobody fell asleep. That's what Grandpa always meant."}, {'id': 'sorry', 'text': 'Grandpa said sorry for 1975. Mr. Rich hugged him, gave back the gold, and the whole town woke up yawning.'}, {'id': 'zero', 'text': "Now Grandpa laughs every single day. With people. Dad's jokes, though? Still zero laughs. Some things never change."}]
TITLES = [('@rule+0.4', '@rule+2.0', 'LAUGH = SLEEP'), ('@bank+0.4', '@bank.end+0.3', 'ROBBED'), ('@noon+0.4', '@noon+2.0', 'SNORING'), ('@fair+0.4', '@fair.end+0.3', '1975'), ('@with+0.4', '@with+2.0', 'WITH US')]
